  box: '<svg viewBox="0 0 24 24" stroke="#5b3a32" stroke-width="2" stroke-linejoin="round"><path d="M3 9h18v11a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 20z" fill="#f3c58f"/><path d="M2 5.5A1.5 1.5 0 0 1 3.5 4h17A1.5 1.5 0 0 1 22 5.5V9H2z" fill="#ffb3c1"/><rect x="9" y="12" width="6" height="3" rx="1.5" fill="#fff7ec"/></svg>',
