  if (k === 's') { S.stars += v; return { icon: UI.star, txt: `별 +${v}` }; }
  if (k === 'bag') { const ok = placeItem(makeBag(v)); renderBoard(); return { icon: iconBag(v), txt: BAG_NAMES[v], sub: ok ? '판에 놓았어요' : '판에 자리가 나면 와요' }; }
