  let sub = '보관함에 넣었어요';
  if (h) h.n = tN(h) + 1; else if (e >= 0) S.store[e] = { tool: k }; else sub = placeItem({ tool: k }) ? '판에 놓았어요' : '판에 자리가 나면 와요';
  renderInfo(); renderBoard();
