function openDraw() {
  const m = modal(`<h3>행운 뽑기</h3>
    <div class="mc-sec mc-draw" style="text-align:center;padding:16px 10px">
      <div class="dr-ic" style="width:84px;height:84px;margin:0 auto">${DRAW_ICON()}</div>
      <div class="dr-tx" style="font-size:18px;margin-top:8px">무엇이 나올까요?</div>
      <div class="mc-sub" style="margin-top:4px">에너지 · 보따리 · 가위 · 스프링클 · 별</div>
    </div>
    <div class="acts"><button class="mc-btn wh" data-x>닫기</button><button class="mc-btn pk" data-go><i>${UI.coin}</i><span class="pr"></span> 뽑기</button></div>`);
  const go = m.querySelector('[data-go]'), ic = m.querySelector('.dr-ic'), tx = m.querySelector('.dr-tx');
  const upd = () => { const p = drawPrice(); go.querySelector('.pr').textContent = p; go.disabled = S.coins < p; };
  upd();
  go.addEventListener('click', () => {
    const p = drawPrice(); if (S.coins < p) { sfx('error'); return; }
    S.coins -= p;
    let r = Math.random() * DRAW.reduce((a, d) => a + d[2], 0), d = DRAW[0];
    for (const x of DRAW) { r -= x[2]; if (r < 0) { d = x; break; } }
    const got = drawGive(d[0], d[1]);
    ic.innerHTML = got.icon; tx.textContent = got.txt; m.querySelector('.mc-draw .mc-sub').textContent = got.sub || '받았어요!';
    jelly(ic, 1, 460); const rr = ic.getBoundingClientRect(); ring(rr); burst(rr); sfx('decor'); haptic(14);
    renderTop(); upd(); save();
  });
}
