  const A = AREAS[curArea];
  if (!areaOpen(curArea)) { box.innerHTML = ''; return; }
  const cu = curOf(A), gate0 = A.event && D('xbase') < 1;
  let d = k && A.spots.find(x => x.k === k);
  if (!d || D(d.k) >= 2) {
    d = A.spots.filter(x => D(x.k) < 2 && !(gate0 && x.k !== 'xbase')).sort((p, q) => p.costs[D(p.k)] - q.costs[D(q.k)])[0];
  }
  if (!d) { box.innerHTML = `<div class="cf-done"><b>${esc(A.name)} 완성!</b><span class="mc-sub">${A.perk ? `완성 보너스 · ${esc(A.perk)} 적용 중` : '마을에서 구경해 보세요'}</span></div>`; cfPop = null; return; }
